-- ════════════════════════════════════════════════════════════════════════
-- All of West Bengal, and "Add your town".
--
-- 1. A report anywhere in West Bengal is accepted. Purulia's own blocks,
--    wards and panchayats come first (locate), then the wards of another
--    town on the map (locate_place), then the district (locate_district):
--    a spot in no mapped ward is filed under its district, with
--    place = 'district:<slug>', so every Purulia page and count (which read
--    place is null) stays Purulia-only. District outlines: the Local
--    Government Directory's, from india-geodata (CC0), simplified to ~200 m;
--    tools/build-districts.py builds the rows below.
--
-- 2. Anyone can send a town's ward map, uploaded as GeoJSON or drawn on the
--    map (add-town.html), with who is in charge of cleaning and where that
--    was found. Nothing goes live until a moderator approves it. Drawn maps
--    go live as "provisional, community-drawn". A disputed border is fixed
--    by sending just the corrected wards (fix_of); approving replaces those
--    wards and keeps the rest.
--
-- Safe to re-run.
-- ════════════════════════════════════════════════════════════════════════

begin;

alter table kasa_private.areas drop constraint if exists areas_kind_check;
alter table kasa_private.areas add constraint areas_kind_check
  check (kind in ('block', 'ward', 'town', 'gp', 'place_ward', 'district'));

alter table public.reports add column if not exists district text;

alter table kasa_private.places
  add column if not exists district        text,
  add column if not exists status          text not null default 'live',
  add column if not exists community       boolean not null default false,
  add column if not exists incharge        text,
  add column if not exists incharge_source text,
  add column if not exists updated_at      timestamptz not null default now();
alter table kasa_private.places drop constraint if exists places_status_check;
alter table kasa_private.places add constraint places_status_check check (status in ('live', 'provisional'));
update kasa_private.places set district = 'Kolkata' where slug = 'kolkata' and district is null;

-- ── District rows: generated by tools/build-districts.py, do not edit by hand ──
delete from kasa_private.areas where kind = 'district';
insert into kasa_private.areas (id, kind, name, ward_no, min_lat, max_lat, min_lng, max_lng, polygons, parent) values
