grant execute on function public.kasa_places() to anon, authenticated;
revoke all on function public.kasa_place_wards(text) from public;
grant execute on function public.kasa_place_wards(text) to anon, authenticated;
revoke all on function public.kasa_submit_place(text, text, text, text, text, text, text, text, boolean, text, jsonb, text) from public;
grant execute on function public.kasa_submit_place(text, text, text, text, text, text, text, text, boolean, text, jsonb, text) to anon, authenticated;
revoke all on function public.kasa_admin_place_submissions() from public, anon;
grant execute on function public.kasa_admin_place_submissions() to authenticated;
revoke all on function public.kasa_admin_review_place(bigint, text, text, text) from public, anon;
grant execute on function public.kasa_admin_review_place(bigint, text, text, text) to authenticated;

